# src/workpeg/build.py
import subprocess
import sys
from pathlib import Path
from typing import Callable

from workpeg.config import load_function_config
from workpeg.function_check import BundleRefused, check_config, check_files

#: What Workpeg's install adds to every function build (the api's
#: BUILD_ARGV_HEAD): pull the base from the registry and give no RUN step a
#: network. The platform is what Workpeg runs, so an Apple silicon Mac
#: builds the image Workpeg would, with the x86_64 wheels the docs vendor,
#: instead of an arm64 one. ``--like-workpeg`` builds with these.
WORKPEG_BUILD_FLAGS = ("--pull", "--network=none", "--platform=linux/amd64")


def slugify(value: str) -> str:
    return value.lower().replace("_", "-").replace(".", "-").replace(" ", "-")


def default_image_name(project_path: Path) -> str:
    project_name = slugify(project_path.resolve().name)
    return f"workpeg-fn-{project_name}"


def validate_function_project(path: Path) -> None:
    """Raise a descriptive error if *path* is not a valid function project."""
    if not path.exists():
        raise FileNotFoundError(f"Project path not found: {path}")

    if not path.is_dir():
        raise NotADirectoryError(f"Expected a project directory, got a file: {path}")

    if not (path / "Dockerfile").exists():
        raise FileNotFoundError(
            f"No Dockerfile found in '{path}'. "
            "Run 'workpeg function new <name>' to scaffold a project."
        )

    if not (path / "app" / "main.py").exists():
        raise FileNotFoundError(
            f"No app/main.py found in '{path}'. "
            "Run 'workpeg function new <name>' to scaffold a project."
        )


def build_image(
    path: str = ".",
    tag: str | None = None,
    timeout: "float | None" = None,
    like_workpeg: bool = False,
    output: "Callable[[str], None] | None" = None,
) -> str:
    """Build the function at *path* and return the image's tag.

    The Dockerfile is checked first, by the rules Workpeg's install applies
    (workpeg.function_check), and a Dockerfile Workpeg would refuse is
    refused here with the same message, before Docker runs: a build that
    succeeds locally on a Dockerfile Workpeg refuses tells the developer
    nothing true. A ``build.image`` in workpeg.json is still used as the
    local tag, with a warning, because only the upload is refused for it.

    *like_workpeg* adds WORKPEG_BUILD_FLAGS, so the build fails here when a
    step downloads, or when the wheels are not for linux/amd64.

    *output*, when given, takes what Docker prints instead of the terminal
    (stdout and stderr together, once the build ends, whether it passed or
    failed), and the ``build.image`` warning too, so that a caller can
    escape it before it is printed: a Dockerfile's RUN steps print
    whatever they like."""
    project_path = Path(path).resolve()

    validate_function_project(project_path)
    check_files(project_path)
    try:
        check_config(project_path)
    except BundleRefused as refused:
        warning = (f"WARNING: {refused} `workpeg function submit` will "
                   "refuse this project.")
        if output is None:
            print(warning, file=sys.stderr)
        else:
            output(warning)

    cfg = load_function_config(project_path)

    image = tag or cfg.get("build", {}).get("image") or default_image_name(project_path)

    argv = ["docker", "build"]
    if like_workpeg:
        argv += WORKPEG_BUILD_FLAGS
    argv += ["-t", image, str(project_path)]

    captured = {} if output is None else {
        "stdout": subprocess.PIPE, "stderr": subprocess.STDOUT,
        "text": True, "errors": "replace"}
    try:
        done = subprocess.run(
            argv,
            check=output is None,
            timeout=timeout,
            **captured,
        )
    except FileNotFoundError as exc:
        raise RuntimeError(
            "Docker not found. Install Docker Desktop or ensure the 'docker' "
            "command is on your PATH."
        ) from exc
    except subprocess.TimeoutExpired as exc:
        if output is not None and exc.output:
            output(exc.output if isinstance(exc.output, str)
                   else exc.output.decode("utf-8", "replace"))
        raise RuntimeError(
            f"Docker build timed out after {timeout}s — it never finished, so "
            "the run was abandoned rather than left hanging."
        ) from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Docker build failed (exit {exc.returncode}). "
            "Check the output above for details."
        ) from exc

    if output is not None:
        if done.stdout:
            output(done.stdout)
        if done.returncode != 0:
            raise RuntimeError(
                f"Docker build failed (exit {done.returncode}). "
                "Check the output above for details.")
    return image
